css:
@font-face{font-family:'JB';src:url(node_modules/@fontsource/jetbrains-mono/files/jetbrains-mono-latin-500-normal.woff2);font-weight:500;}@font-face{font-family:'JB';src:url(node_modules/@fontsource/jetbrains-mono/files/jetbrains-mono-latin-800-normal.woff2);font-weight:800;}
.card{background:#0A0A0A;color:#EDEDED;font-family:'JB';}
.card::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(0deg,rgba(255,255,255,.035) 0 2px,transparent 2px 6px);}
.bar{position:absolute;top:120px;left:80px;right:140px;display:flex;justify-content:space-between;font:500 34px 'JB';color:#7F906A;border-bottom:3px solid #2A3320;padding-bottom:18px;}
.safe{justify-content:center;}
.prompt{font:800 46px 'JB';color:#B6FF3B;margin:0 0 30px;}
.prompt::before{content:'$ ';color:#6F7F5A;}
h1{font:800 112px/1.02 'JB';letter-spacing:-4px;margin:0;color:#B6FF3B;}
h2{font:800 110px/1.05 'JB';letter-spacing:-3px;margin:0 0 30px;color:#B6FF3B;}
.cur::after{content:'█';color:#B6FF3B;margin-left:8px;}
.line{font:500 56px/1.3 'JB';margin:22px 0 0;color:#EDEDED;}
.line b{color:#FFB000;font-weight:800;}
.ok{font:500 54px/1.28 'JB';margin:20px 0 0;padding:18px 24px;border:3px solid #B6FF3B;color:#EDEDED;}
.ok::before{content:'[OK] ';color:#B6FF3B;font-weight:800;}
.hit{font:800 64px/1.25 'JB';margin:16px 0;color:#EDEDED;}
.hit::before{content:'> ';color:#FFB000;}
.note{font:500 44px/1.3 'JB';color:#A3B38A;margin-top:34px;}
.card-1 h1{font-size:122px;}
.end h1{font-size:104px;}
.handle{font:800 54px 'JB';color:#FFB000;margin-top:44px;}
.safe{padding-top:60px;}
